/**
 * Schedules each task in the microtask queue and gathers results.
 */
function runMicrotaskBatch(tasks) {
  return new Promise((resolve) => {
    const results = [];
    let completed = 0;

    if (tasks.length === 0) return resolve([]);

    tasks.forEach((task, index) => {
      queueMicrotask(() => {
        results[index] = task();
        completed++;
        if (completed === tasks.length) {
          resolve(results);
        }
      });
    });
  });
}

function createBatcher(flushCallback) {
  let batch = [];
  let isScheduled = false;

  return function add(item) {
    batch.push(item);

    if (!isScheduled) {
      isScheduled = true;
      queueMicrotask(() => {
        const itemsToFlush = [...batch];
        batch = [];
        isScheduled = false;
        flushCallback(itemsToFlush);
      });
    }
  };
}

