async function* asyncTransformStream(items, transformFn) {
  for (const item of items) {
    const transformed = await transformFn(item);
    yield transformed;
  }
}

function runCoroutine(genFactory) {
  return new Promise((resolve, reject) => {
    const gen = genFactory();

    function step(nextFn) {
      let result;
      try {
        result = nextFn();
      } catch (err) {
        return reject(err);
      }

      if (result.done) {
        return resolve(result.value);
      }

      Promise.resolve(result.value)
        .then(value => step(() => gen.next(value)))
        .catch(err => step(() => gen.throw(err)));
    }

    step(() => gen.next());
  });
}
